"""Interfaz del panel local."""

PAGE = r'''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ivko · Centro de control</title>
<style>
:root{font-family:Segoe UI,Arial,sans-serif;color:#24352a;background:#f3f6f3;--g:#276347;--m:#e6f2ea;--l:#e4ebe5;--muted:#6f7e73}*{box-sizing:border-box}body{margin:0}button,input,textarea,select{font:inherit}button{cursor:pointer;border:0;border-radius:9px;padding:10px 14px;background:var(--g);color:white;font-weight:650}button:disabled{opacity:.5;cursor:default}.soft{background:var(--m);color:#27553a}.red{background:#a43b36}.sm{padding:6px 10px;font-size:13px}.shell{min-height:100vh;display:grid;grid-template-columns:220px 1fr}.side{background:#173e2d;color:white;padding:20px 12px}.brand{font-weight:700;font-size:20px;padding:8px}.brand small{display:block;font-size:12px;color:#bed4c6;margin-top:5px}.nav{display:grid;gap:6px;margin-top:20px}.nav button{text-align:left;background:transparent;color:#e2ede5}.nav button.active{background:#ffffff20}.main{min-width:0}.top{background:white;border-bottom:1px solid var(--l);padding:15px 22px;display:flex;align-items:center;gap:10px;position:sticky;top:0;z-index:2;flex-wrap:wrap}.top h1{font-size:20px;margin:0}.acct{font-size:13px;color:var(--muted)}.state{margin-left:auto;background:#fff2d4;color:#66531a;border-radius:20px;padding:8px 12px}.state.on{background:#e3f4e7;color:#23603a}.view{display:none;padding:20px;max-width:1500px;margin:auto}.view.on{display:block}.grid{display:grid;gap:14px}.cards{grid-template-columns:repeat(5,1fr)}.two{grid-template-columns:1fr 1fr}.card{background:white;border:1px solid var(--l);border-radius:12px;padding:16px;box-shadow:0 3px 10px #17351f0b;min-width:0}.kpi small,.muted{color:var(--muted)}.kpi strong{display:block;font-size:27px;margin-top:7px}h2{font-size:17px;margin:0 0 12px}h3{font-size:14px;margin:14px 0 6px}.note{background:#f1f7f3;border-left:3px solid #6da27b;border-radius:5px;padding:10px 12px;color:#526358;font-size:13px;line-height:1.5}.warn{background:#fff8e5;border-left-color:#d7aa3e}.bad{background:#fdecea;border-left-color:#a43b36}.row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.between{justify-content:space-between}.toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.toolbar select,select{padding:9px;border:1px solid var(--l);border-radius:8px;background:white}.layout{display:grid;grid-template-columns:minmax(280px,36%) 1fr;gap:14px}.items{display:grid;gap:8px;max-height:62vh;overflow:auto}.item{width:100%;text-align:left;background:white;color:#263b2e;border:1px solid var(--l);padding:9px;display:grid;grid-template-columns:56px 1fr;gap:10px;align-items:center}.item.sel{border:2px solid var(--g)}.thumb{width:56px;height:56px;object-fit:cover;border-radius:6px;background:#eee}.name{font-weight:650}.small{font-size:12px;color:var(--muted);margin-top:4px}.pill{font-size:11px;padding:4px 8px;border-radius:14px;background:var(--m);color:#285c3b;white-space:nowrap}.pill.auto{background:#e7eefb;color:#2c4f8a}.pill.err{background:#fdecea;color:#8a2c28}.detail{display:grid;grid-template-columns:minmax(180px,38%) 1fr;gap:16px}.preview{width:100%;max-height:66vh;object-fit:contain;background:#edf0ed;border-radius:8px}.field{margin:10px 0}.field label{display:block;font-weight:650;font-size:13px;margin-bottom:5px}.field input,.field textarea{width:100%;padding:10px;border:1px solid #cbd5ce;border-radius:8px}.field input[type=color]{height:42px;padding:3px}.field textarea{height:110px;resize:vertical}.check{display:flex;gap:8px;align-items:flex-start;margin:8px 0}.check input{margin-top:4px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.message-list{display:grid;gap:8px;max-height:64vh;overflow:auto}.message{padding:12px;border:1px solid var(--l);border-radius:9px}.message p{white-space:pre-wrap}.rank{display:grid;grid-template-columns:100px 1fr 90px;gap:8px;align-items:center;margin:9px 0;font-size:13px}.bar{height:12px;background:#eaf0eb;border-radius:10px;overflow:hidden}.bar span{display:block;height:100%;background:#438760}.toast{display:none;position:fixed;right:20px;bottom:20px;padding:12px 16px;border-radius:9px;background:#173e2d;color:white;max-width:420px;z-index:9}table{width:100%;border-collapse:collapse}td,th{padding:8px 6px;border-bottom:1px solid var(--l);text-align:left;font-size:13px;vertical-align:middle}.status{display:grid;gap:8px}.st{display:flex;gap:10px;align-items:center;padding:9px 10px;border-radius:8px;background:#f6f8f6;font-size:14px}.dot{width:10px;height:10px;border-radius:50%;background:#d7aa3e;flex:none}.dot.ok{background:#3d8b5c}.dot.no{background:#a43b36}.st .grow{flex:1}.log{background:#14251b;color:#cfe3d5;font:12px/1.5 Consolas,monospace;padding:12px;border-radius:8px;max-height:320px;overflow:auto;white-space:pre-wrap;margin:0}.bank{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px}.photo{border:1px solid var(--l);border-radius:10px;overflow:hidden;background:white;display:flex;flex-direction:column}.photo img{width:100%;aspect-ratio:4/5;object-fit:cover;background:#eee}.photo.off img{opacity:.35}.photo .body{padding:10px;display:grid;gap:6px}.photo textarea{width:100%;height:58px;padding:7px;border:1px solid #cbd5ce;border-radius:7px;resize:vertical;font-size:13px}.steps{margin:6px 0 12px;padding-left:20px;line-height:1.7;font-size:14px}.steps code,.mono{background:#eef3ef;padding:1px 5px;border-radius:4px;font-family:Consolas,monospace;font-size:13px;word-break:break-all}.savebar{position:sticky;bottom:0;background:#f3f6f3ee;padding:12px 0;display:flex;gap:8px;justify-content:flex-end;border-top:1px solid var(--l);margin-top:14px}@media(max-width:1100px){.cards{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){.shell{grid-template-columns:1fr}.side{position:sticky;top:0;z-index:3;padding:8px}.brand{display:none}.nav{grid-template-columns:repeat(7,1fr);margin:0}.nav button{text-align:center;padding:8px 2px;font-size:12px}.top{top:48px}.cards{grid-template-columns:repeat(2,1fr)}.two,.layout,.detail{grid-template-columns:1fr}.items{max-height:30vh}.state{margin-left:0}}
</style>
<div class="shell"><aside class="side"><div class="brand">IVKO MADERAS<small>Centro de control · Instagram</small></div><nav class="nav"><button class="active" data-v="home">Resumen</button><button data-v="content">Contenido</button><button data-v="bank">Fotos</button><button data-v="messages">Mensajes</button><button data-v="metrics">Métricas</button><button data-v="ads">Publicidad</button><button data-v="settings">Ajustes</button></nav></aside>
<main class="main"><header class="top"><div><h1 id="title">Resumen</h1><div class="acct">Cuenta protegida · @ivkomaderas_</div></div><span id="state" class="state">Consultando…</span><button id="start" onclick="bot('start')">Iniciar</button><button id="restart" class="soft" onclick="bot('restart')">Reiniciar</button><button id="stop" class="red" onclick="bot('stop')">Detener</button></header>

<section id="home" class="view on"><div id="kpis" class="grid cards"></div>
<div class="grid two" style="margin-top:14px"><div class="card"><div class="row between"><h2>Próximas publicaciones</h2><div class="row"><button class="soft sm" onclick="planNow()">Planificar ahora</button><button class="soft sm" onclick="show('content')">Ver todo</button></div></div><div id="upcoming"></div></div>
<div class="card"><h2>Estado del bot</h2><div id="status" class="status"></div></div></div>
<div class="grid two" style="margin-top:14px"><div class="card"><h2>Publicaciones con error</h2><div id="errors"></div></div><div class="card"><div class="row between"><h2>Actividad reciente</h2><button class="soft sm" onclick="loadHome()">Actualizar</button></div><pre id="log" class="log"></pre></div></div></section>

<section id="content" class="view"><div class="toolbar"><input id="files" type="file" hidden accept="image/*,.heic,.heif" multiple onchange="upload(this.files,'borradores')"><button onclick="document.getElementById('files').click()">Crear borradores con fotos</button><button class="soft" onclick="loadPosts()">Actualizar</button><select id="filter" onchange="renderPosts()"><option value="todos">Todos</option><option value="aprobada">Programadas</option><option value="borrador">Borradores</option><option value="publicada">Publicadas</option><option value="error">Con error</option><option value="salteada">Salteadas</option><option value="rechazada">Rechazadas</option><option value="vencida">Vencidas</option></select><span class="muted">El piloto automático programa solo; acá podés revisar, editar o cambiar cada publicación.</span></div><div class="layout"><div class="card"><h2>Publicaciones e historias</h2><div id="posts" class="items"></div></div><div class="card"><div id="editor" class="muted">Elegí una publicación para revisarla.</div></div></div></section>

<section id="bank" class="view"><div class="toolbar"><input id="bankFiles" type="file" hidden accept="image/*,.heic,.heif" multiple onchange="upload(this.files,'banco')"><button onclick="document.getElementById('bankFiles').click()">Subir fotos al banco</button><button class="soft" onclick="planNow()">Traer de Drive y planificar</button><span id="bankSummary" class="muted"></span></div><div class="note" style="margin-bottom:12px">El texto de cada foto es el <b>pie de foto</b> que se usa cuando sale como post. Elegí si cada foto es para historias, publicaciones o ambas (también podés escribir <b>(historia)</b> o <b>(publicacion)</b> en el nombre o en el texto que mandás por Telegram). Las fotos pausadas no se usan. Los posts nunca repiten foto; las historias rotan empezando por la que hace más tiempo que no salió.</div><div id="bankGrid" class="bank"></div></section>

<section id="messages" class="view"><div class="grid two"><div class="card"><div class="row between"><h2>Mensajes recibidos</h2><button class="soft" onclick="loadMessages()">Actualizar</button></div><div id="tgState" class="note"></div><div id="msgs" class="message-list" style="margin-top:8px"></div></div><div class="card"><h2>Responder por Instagram</h2><div id="replyInfo" class="note">Elegí un mensaje pendiente.</div><div class="field"><label>Respuesta</label><textarea id="replyText" placeholder="Escribí tu respuesta"></textarea></div><button id="sendReply" onclick="sendReply()" disabled>Enviar respuesta</button><p class="muted">Instagram solo permite responder dentro de las 24 h del último mensaje de la persona.</p></div></div></section>

<section id="metrics" class="view"><div class="toolbar"><button onclick="syncMetrics()">Sincronizar métricas</button><a href="/api/export?sync=1" onclick="toast('Generando el Excel con datos actualizados…')"><button class="soft" type="button">Descargar Excel para Power BI</button></a><span id="syncState" class="muted">Horarios basados en el rendimiento de tus publicaciones.</span></div><div id="mKpis" class="grid cards"></div><div class="grid two" style="margin-top:14px"><div class="card"><h2>Interacción por hora</h2><div id="hourChart"></div><p id="metricNote" class="muted"></p></div><div class="card"><h2>Mejores días y horas</h2><div id="peak"></div><div id="audienceNote" class="note"></div></div></div><div class="card" style="margin-top:14px"><h2>Publicaciones destacadas</h2><div id="topPosts"></div></div></section>

<section id="ads" class="view">
<div class="grid two"><div class="card"><div class="row between"><h2>Presupuesto de este mes</h2><button class="soft sm" onclick="adsRefresh()">Actualizar gasto</button></div><div id="adsSpend"></div></div>
<div class="card"><h2>Estado</h2><div id="adsStatus" class="status"></div><div class="actions"><button id="adsToggleBtn" onclick="adsToggle()">…</button><button class="soft" onclick="act('ads_check')">Verificar cuenta</button></div></div></div>

<div class="grid two" style="margin-top:14px"><div class="card"><h2>Presupuesto mensual</h2><div class="grid two"><div class="field"><label>Monto por mes (en la moneda de tu cuenta)</label><input id="adsBudget" type="number" min="1" step="1" placeholder="Ej: 60000"></div><div class="field"><label>Objetivo</label><select id="adsGoal" style="width:100%"><option value="mensajes">Mensajes por DM</option><option value="alcance">Alcance (más personas)</option></select></div></div><button onclick="adsBudget()">Guardar presupuesto</button><p class="muted">Cada mes el bot crea una campaña con este monto total y fecha de fin el último día. Meta lo reparte día a día y <b>no puede gastar más</b>. Si la activás a mitad de mes, usa solo la parte proporcional a los días que quedan. Al empezar el mes siguiente renueva la campaña sola.</p></div>
<div class="card"><h2>Zonas donde se muestra</h2><div class="row"><input id="zoneQ" placeholder="Buscar: Palermo, Vicente López, Córdoba, 1425…" style="flex:1;padding:10px;border:1px solid #cbd5ce;border-radius:8px" onkeydown="if(event.key==='Enter')zoneSearch()"><button class="soft" onclick="zoneSearch()">Buscar</button></div><div id="zoneResults" style="margin-top:8px"></div><h3>Zonas elegidas</h3><div id="zoneList"></div><p class="muted">Ciudades admiten un radio de 17 a 80 km alrededor. Los cambios se aplican enseguida a la campaña del mes.</p></div></div>

<div class="card" style="margin-top:14px"><h2>Publicaciones a promocionar</h2><p class="muted">Elegí qué publicaciones promocionar. El presupuesto del mes se reparte entre todas las elegidas; Meta le da más a la que mejor funciona.</p><div id="adsPosts" class="bank"></div></div>

<div class="card" style="margin-top:14px"><h2>Conectar la cuenta publicitaria de Meta</h2><div id="adsSetup" class="note warn"></div>
<ol class="steps"><li>Entrá a <b>business.facebook.com</b> → <b>Configuración del negocio</b> → <b>Usuarios → Usuarios del sistema</b> → <b>Agregar</b> (rol Administrador).</li><li>Con ese usuario elegido, tocá <b>Asignar activos</b> y dale <b>control total</b> de tu <b>cuenta publicitaria</b>, tu <b>Página de Facebook</b> y tu <b>cuenta de Instagram</b>.</li><li>Tocá <b>Generar token</b>, elegí la app <b>bot pisos</b>, vencimiento <b>Nunca</b>, y marcá los permisos: <code>ads_management</code>, <code>ads_read</code>, <code>business_management</code>, <code>pages_show_list</code>, <code>pages_read_engagement</code>, <code>pages_manage_ads</code>, <code>instagram_basic</code>.</li><li>Pegá el token acá y tocá <b>Conectar</b>. Después elegí tu cuenta publicitaria de la lista.</li></ol>
<div class="row"><input id="adsToken" type="password" autocomplete="new-password" placeholder="Token de Meta (no se vuelve a mostrar)" style="flex:1;padding:10px;border:1px solid #cbd5ce;border-radius:8px"><button onclick="adsConnect()">Conectar</button></div><div class="row" style="margin-top:8px"><select id="adsAccounts" style="display:none" onchange="adsPickAccount(this.value)"></select></div>
<p class="muted">La Página de Facebook tiene que estar vinculada a @ivkomaderas_ (Instagram → Configuración → Centro de cuentas). Es un requisito de Meta para los anuncios que llevan a mensajes.</p></div>
</section>

<section id="settings" class="view">
<div class="grid two">
<div class="card"><h2>Funcionamiento</h2><div id="opStatus" class="status"></div><div class="actions"><button id="autoBtn" class="soft" onclick="toggleAutostart()">…</button><button class="soft" onclick="act('test_instagram')">Probar Instagram</button><button class="soft" onclick="renewToken()">Renovar token ahora</button></div><p class="muted">El inicio automático hace que el bot arranque solo, en segundo plano, cada vez que prendés la PC. La PC no tiene que suspenderse para que publique.</p></div>
<div class="card"><h2>Piloto automático</h2><label class="check"><input id="autopilot" type="checkbox"><span><b>Publicar solo</b>: una historia por día y un post por semana con las fotos del banco. Te avisa por Telegram antes, con opción de cambiar la foto o saltearla.</span></label><div class="grid two"><div class="field"><label>Hora de la historia (sin métricas suficientes)</label><input id="storyHour" type="number" min="0" max="23"></div><div class="field"><label>Elegir y avisar el post con (días de anticipación)</label><input id="noticeDays" type="number" min="1" max="6"></div></div><p class="muted">Con suficientes métricas, el bot usa tu mejor día y hora para el post y el horario pico de cada día para la historia.</p></div>
</div>

<div class="card" style="margin-top:14px"><h2>Telegram · avisos y botones</h2><div id="tgSetup" class="note warn"></div>
<ol class="steps"><li>En Telegram buscá <b>@BotFather</b> (tilde azul), enviá <code>/newbot</code>, elegí un nombre y un usuario que termine en <code>bot</code>.</li><li>BotFather te responde con un <b>token</b> (algo como <code>123456:ABC…</code>). Pegalo abajo y tocá <b>Guardar ajustes</b>.</li><li>Abrí el chat con tu bot nuevo (el link <code>t.me/…</code> que te dio BotFather) y enviá <code>/start</code>.</li><li>Tocá <b>Detectar chat</b>, elegí tu nombre en la lista y volvé a tocar <b>Guardar ajustes</b>.</li><li>Tocá <b>Enviar prueba</b>: te tiene que llegar un mensaje al celular.</li></ol>
<div class="grid two"><div class="field"><label>Token de BotFather</label><input id="tgToken" type="password" autocomplete="new-password" placeholder="Se guarda localmente y no vuelve a mostrarse"></div><div class="field"><label>Chat ID</label><input id="tgChat" placeholder="Se completa al detectar el chat"></div></div>
<div class="row"><button class="soft" onclick="discover()">Detectar chat</button><select id="tgCandidates" onchange="pickChat()"><option value="">Chats detectados</option></select><button class="soft" onclick="act('test_telegram')">Enviar prueba</button></div></div>

<div class="card" style="margin-top:14px"><h2>Google Drive · de dónde salen las fotos</h2><div id="driveSetup" class="note warn"></div>
<ol class="steps"><li>Entrá a <b>console.cloud.google.com</b>, creá un proyecto y en <b>APIs y servicios → Biblioteca</b> habilitá <b>Google Drive API</b>.</li><li>En <b>Credenciales → Crear credenciales → Cuenta de servicio</b>, creala; después en su pestaña <b>Claves → Agregar clave → JSON</b>. Se descarga un archivo.</li><li>Subí ese archivo acá: <input id="credFile" type="file" hidden accept=".json,application/json" onchange="uploadCred(this.files[0])"><button class="soft sm" onclick="document.getElementById('credFile').click()">Subir archivo JSON</button></li><li>En Drive creá una carpeta y <b>compartila como Editor</b> con: <span id="driveAccount" class="mono">(subí primero el JSON)</span></li><li>Pegá abajo el link de esa carpeta, guardá y tocá <b>Probar Drive</b>.</li></ol>
<div class="field"><label>Link o ID de la carpeta de Drive</label><input id="driveFolder" placeholder="https://drive.google.com/drive/folders/…"></div><div class="row"><button class="soft" onclick="act('test_drive')">Probar Drive</button></div></div>

<div class="card" style="margin-top:14px"><h2>Diseño y textos</h2><div class="grid two"><div class="field"><label>Texto para historias (varias opciones separadas por |)</label><input id="storyText"></div><div class="field"><label>Botón de las historias (varias opciones separadas por |)</label><input id="storyCta"></div><div class="field"><label>Nombre de marca en la historia (opcional)</label><input id="brand"></div><div class="field"><label>Color del botón</label><input id="brandColor" type="color"></div><div class="field"><label>Hashtags (para fotos con nombre de cámara)</label><input id="hashtags"></div><div class="field"><label>Cierre del post (para fotos con nombre de cámara)</label><input id="closing"></div><div class="field"><label>WhatsApp (código de país, solo números)</label><input id="whatsapp" placeholder="5491112345678"></div><div class="field"><label>Revisar cada (minutos)</label><input id="interval" type="number" min="1" max="60"></div></div><div class="field"><label>Descripción del negocio (para la IA)</label><textarea id="business"></textarea></div><p class="muted">Los cambios de diseño se aplican a las historias que se programen desde ahora.</p></div>

<div class="card" style="margin-top:14px"><h2>IA (opcional)</h2><div id="aiStatus" class="note"></div><div class="field"><label>Clave de Anthropic</label><input id="aiKey" type="password" autocomplete="new-password" placeholder="Se guarda localmente y no vuelve a mostrarse"></div><label class="check"><input id="aiOn" type="checkbox"><span>Usar IA para sugerir respuestas y escribir pies de foto cuando la foto tiene nombre de cámara.</span></label><label class="check"><input id="autoOn" type="checkbox"><span>Enviar respuestas automáticas a clientes.</span></label><p class="muted">Con IA activa, los textos de los mensajes y las fotos se envían a Anthropic.</p></div>
<div class="savebar"><button onclick="saveSettings()">Guardar ajustes</button></div>
</section>
</main></div><div id="toast" class="toast"></div>
<script>
var posts=[],selected=null,dirty=false,messages=[],selectedMessage=null,settings={},bankData={photos:[]};var days=['lun','mar','mié','jue','vie','sáb','dom'];
var estados={borrador:'borrador',aprobada:'programada',publicada:'publicada',error:'error',salteada:'salteada',rechazada:'rechazada',vencida:'vencida',publicando:'publicando'};
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
async function api(path,body){var r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});var d=await r.json();if(!r.ok)throw Error(d.error||'No se pudo completar');return d}
function toast(t){var e=document.getElementById('toast');e.textContent=t;e.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(function(){e.style.display='none'},4500)}
async function act(a,extra){try{var d=await api('/api/action',Object.assign({action:a},extra||{}));toast(d.message||'Listo');return d}catch(e){alert(e.message)}}
function fecha(t){if(!t)return '';var d=new Date(t);return days[(d.getDay()+6)%7]+' '+t.slice(8,10)+'/'+t.slice(5,7)+' '+t.slice(11,16)}
function pill(p){return '<span class="pill '+(p.estado==='error'?'err':'')+'">'+esc(estados[p.estado]||p.estado)+'</span>'+(p.auto?' <span class="pill auto">automática</span>':'')}
function show(id){if(dirty&&!confirm('Hay cambios sin guardar. ¿Descartarlos?'))return;dirty=false;document.querySelectorAll('.view').forEach(function(x){x.classList.toggle('on',x.id===id)});document.querySelectorAll('.nav button').forEach(function(x){x.classList.toggle('active',x.dataset.v===id)});document.getElementById('title').textContent={home:'Resumen',content:'Contenido',bank:'Banco de fotos',messages:'Mensajes',metrics:'Métricas',ads:'Publicidad',settings:'Ajustes'}[id];if(id==='ads')loadAds();if(id==='home')loadHome();if(id==='content')loadPosts();if(id==='bank')loadBank();if(id==='messages')loadMessages();if(id==='metrics')loadMetrics();if(id==='settings')loadSettings()}
document.querySelectorAll('.nav button').forEach(function(b){b.onclick=function(){show(b.dataset.v)}});
document.addEventListener('input',function(e){if(['caption','when','storyTextEdit','storyCtaEdit'].includes(e.target.id))dirty=true});
function st(ok,text,action){return '<div class="st"><span class="dot '+(ok===true?'ok':ok===false?'no':'')+'"></span><span class="grow">'+text+'</span>'+(action||'')+'</div>'}
function cfg(){return '<button class="soft sm" onclick="show(\'settings\')">Configurar</button>'}
function setRunning(r){var s=document.getElementById('state');s.textContent=r?'Bot funcionando':'Bot detenido';s.classList.toggle('on',r);document.getElementById('start').disabled=r;document.getElementById('stop').disabled=!r;document.getElementById('restart').disabled=!r}
function upcomingRow(p){return '<tr><td><b>'+esc(p.name)+'</b><div class="small">'+esc(p.tipo)+(p.auto?' · automática':'')+'</div></td><td>'+fecha(p.display_time)+'</td><td>'+(p.auto?'<div class="row"><button class="soft sm" onclick="swapPost('+p.id+')">Otra foto</button><button class="soft sm" onclick="skipPost('+p.id+')">No publicar</button></div>':'')+'</td></tr>'}
async function loadHome(){var d=await api('/api/summary');setRunning(d.running);document.getElementById('kpis').innerHTML=[['Programadas',d.counts.aprobada],['Publicadas',d.counts.publicada],['Con error',d.counts.error],['Mensajes pendientes',d.messages_pending],['Fotos sin usar en feed',d.bank.sin_post+' / '+d.bank.total]].map(function(x){return '<div class="card kpi"><small>'+x[0]+'</small><strong>'+x[1]+'</strong></div>'}).join('');
document.getElementById('upcoming').innerHTML=d.upcoming.length?'<table>'+d.upcoming.map(upcomingRow).join('')+'</table>':'<p class="muted">No hay nada programado. Con el bot encendido y fotos en el banco, el piloto automático programa solo.</p>';
var tok=d.token_renewed?'Token de Instagram renovado el '+d.token_renewed.split('-').reverse().join('/'):'El token de Instagram se renovará solo la primera vez que el bot corra';
document.getElementById('status').innerHTML=st(d.running,d.running?'Bot funcionando':'Bot detenido',d.running?'':'<button class="sm" onclick="bot(\'start\')">Iniciar</button>')+st(d.autostart,d.autostart?'Arranca solo al prender la PC':'No arranca solo al prender la PC',d.autostart?'':cfg())+st(d.autopilot?true:null,d.autopilot?'Piloto automático: historia diaria y post semanal':'Piloto automático apagado: solo publica lo que apruebes',d.autopilot?'':cfg())+st(d.telegram,d.telegram?'Telegram conectado: te llegan los avisos':'Telegram sin conectar: no te llegan avisos',d.telegram?'':cfg())+st(d.drive?true:null,d.drive?'Google Drive conectado':'Google Drive sin conectar (podés subir fotos desde la pestaña Fotos)',d.drive?'':cfg())+st(d.bank.sin_post>=2?true:d.bank.total?null:false,d.bank.total+' fotos en el banco, '+d.bank.sin_post+' sin usar en el feed','<button class="soft sm" onclick="show(\'bank\')">Ver fotos</button>')+st(true,tok)+st(d.ai?true:null,d.ai?'IA disponible':'IA apagada (opcional)');
document.getElementById('errors').innerHTML=d.errors.length?'<table>'+d.errors.map(function(e){return '<tr><td><b>'+esc(e.tipo)+' #'+e.id+'</b><div class="small">'+esc(e.error)+'</div></td><td><div class="row"><button class="sm" onclick="retryPost('+e.id+')">Reintentar</button><button class="soft sm" onclick="cancelPost('+e.id+')">Descartar</button></div></td></tr>'}).join('')+'</table>':'<p class="muted">Sin errores.</p>';
var log=document.getElementById('log');log.textContent=d.log.length?d.log.join('\n'):'Todavía no hay actividad registrada.';log.scrollTop=log.scrollHeight}
async function bot(a){var label={start:'Bot iniciado',stop:'Bot detenido',restart:'Bot reiniciado'}[a];document.getElementById('state').textContent='Un momento…';try{await api('/api/action',{action:a});toast(label)}catch(e){alert(e.message)}await loadHome()}
async function planNow(){toast('Buscando fotos y planificando…');var d=await act('plan_now');if(d){await refreshAll()}}
async function refreshAll(){await loadHome();if(document.getElementById('content').classList.contains('on'))await loadPosts();if(document.getElementById('bank').classList.contains('on'))await loadBank()}
async function swapPost(id){if(!confirm('¿Cambiar la foto de esta publicación por otra del banco?'))return;if(await act('swap',{id:id}))await refreshAll()}
async function skipPost(id){if(!confirm('¿No publicar esta vez? Ese día o esa semana queda sin publicación.'))return;if(await act('skip',{id:id}))await refreshAll()}
async function retryPost(id){if(await act('retry',{id:id}))await refreshAll()}
async function cancelPost(id){if(!confirm('¿Cancelar esta publicación?'))return;if(await act('reject',{id:id})){selected=null;dirty=false;await refreshAll()}}
async function loadPosts(){posts=(await api('/api/posts')).posts;renderPosts()}
function renderPosts(){var f=document.getElementById('filter').value;var arr=posts.filter(function(p){return f==='todos'||p.estado===f});document.getElementById('posts').innerHTML=arr.map(function(p){return '<button class="item '+(selected===p.id?'sel':'')+'" onclick="selectPost('+p.id+')"><img class="thumb" loading="lazy" src="/image/'+p.id+'?v='+encodeURIComponent(p.updated)+'"><div><div class="row">'+pill(p)+'</div><div class="name">'+esc(p.name)+'</div><div class="small">'+esc(p.tipo)+' · '+fecha(p.display_time)+'</div></div></button>'}).join('')||'<p class="muted">Sin contenido para este filtro.</p>';if(selected&&!posts.some(function(p){return p.id===selected}))selected=null;if(selected&&!dirty)renderEditor()}
function selectPost(id){if(dirty&&!confirm('Hay cambios sin guardar. ¿Descartarlos?'))return;dirty=false;selected=id;renderPosts()}
function editable(p){return p.estado==='borrador'||p.estado==='aprobada'}
function renderEditor(){var p=posts.find(function(x){return x.id===selected});if(!p)return;var dis=editable(p)?'':'disabled';var fields=p.tipo==='post'?'<div class="field"><label>Descripción que verá tu audiencia</label><textarea id="caption" '+dis+'>'+esc(p.caption)+'</textarea></div>':'<div class="field"><label>Texto visible en la historia</label><input id="storyTextEdit" value="'+esc(p.story_text)+'" '+dis+'></div><div class="field"><label>Botón de la historia</label><input id="storyCtaEdit" value="'+esc(p.story_cta)+'" '+dis+'></div>';
var info=p.estado==='aprobada'?'<div class="note">Programada: se publica sola en la fecha indicada (con el bot encendido). Todavía podés editarla.</div>':p.estado==='error'?'<div class="note bad">'+esc(p.error)+'</div>':p.estado==='publicada'?'<div class="note">Publicada en Instagram.</div>':'';
var btns='<button class="soft" onclick="savePost()" '+dis+'>Guardar cambios</button>';if(p.estado==='borrador')btns+='<button onclick="approvePost()">Aprobar y programar</button><button class="red" onclick="cancelPost('+p.id+')">Rechazar</button>';if(p.estado==='aprobada'){if(p.auto)btns+='<button class="soft" onclick="swapPost('+p.id+')">Otra foto</button><button class="soft" onclick="skipPost('+p.id+')">No publicar</button>';else btns+='<button class="red" onclick="cancelPost('+p.id+')">Cancelar</button>'}if(p.estado==='error')btns+='<button onclick="retryPost('+p.id+')">Reintentar</button><button class="red" onclick="cancelPost('+p.id+')">Descartar</button>';
document.getElementById('editor').innerHTML='<div class="detail"><div><img class="preview" src="/image/'+p.id+'?v='+encodeURIComponent(p.updated)+'"><p class="muted">Así se va a ver en Instagram.</p></div><div><h2>'+esc(p.name)+'</h2><div class="row">'+pill(p)+'</div>'+info+fields+'<div class="field"><label>Fecha y hora local · Buenos Aires</label><input type="datetime-local" id="when" value="'+esc(p.display_time)+'" '+dis+'></div><div class="actions">'+btns+'</div></div></div>'}
function postPayload(action){var p=posts.find(function(x){return x.id===selected});var ok=editable(p);return {action:action,id:selected,caption:p.tipo==='post'&&ok?document.getElementById('caption').value:null,story_text:p.tipo==='historia'&&ok?document.getElementById('storyTextEdit').value:null,story_cta:p.tipo==='historia'&&ok?document.getElementById('storyCtaEdit').value:null,when:document.getElementById('when').value}}
async function savePost(){try{await api('/api/action',postPayload('save_post'));dirty=false;await loadPosts();await loadHome();toast('Cambios guardados')}catch(e){alert(e.message)}}
async function approvePost(){var p=posts.find(function(x){return x.id===selected});if(!confirm('¿Aprobar '+p.name+' para @ivkomaderas_? Se publicará en la fecha y hora indicadas.'))return;try{await api('/api/action',postPayload('approve'));dirty=false;await loadPosts();await loadHome();toast('Aprobada y programada')}catch(e){alert(e.message)}}
async function upload(files,destino){var n=0;for(var i=0;i<files.length;i++){var f=files[i];if(f.size>15*1024*1024){alert(f.name+' supera 15 MB');continue}toast('Subiendo '+(i+1)+' de '+files.length+'…');var b=await new Promise(function(ok,no){var r=new FileReader();r.onload=function(){ok(r.result.split(',')[1])};r.onerror=no;r.readAsDataURL(f)});try{await api('/api/upload',{name:f.name,data:b,destino:destino});n++}catch(e){alert(f.name+': '+e.message)}}document.getElementById('files').value='';document.getElementById('bankFiles').value='';toast(destino==='banco'?n+' foto(s) agregadas al banco. Revisá el pie de foto de cada una.':'Fotos procesadas; editá cada descripción antes de aprobar');await refreshAll()}
async function loadBank(){bankData=await api('/api/bank');var s=bankData.summary;document.getElementById('bankSummary').textContent=s.total+' fotos · '+s.sin_post+' para publicaciones sin usar · '+s.historias+' para historias';document.getElementById('bankGrid').innerHTML=bankData.photos.map(function(f){return '<div class="photo '+(f.activa?'':'off')+'"><img loading="lazy" src="/bank/'+f.id+'"><div class="body"><div class="row">'+(f.activa?'':'<span class="pill err">pausada</span>')+(f.programada?'<span class="pill auto">programada</span>':'')+'<span class="pill">'+esc(f.origen)+'</span></div><select onchange="useBank('+f.id+',this.value)"><option value=""'+(f.uso===''?' selected':'')+'>Historias y publicaciones</option><option value="historia"'+(f.uso==='historia'?' selected':'')+'>Solo historias</option><option value="post"'+(f.uso==='post'?' selected':'')+'>Solo publicaciones</option></select><textarea id="bn'+f.id+'"'+(f.uso==='historia'?' placeholder="Las historias no llevan pie de foto"':'')+'>'+esc(f.nombre)+'</textarea><div class="small">Posts: '+f.usos_post+' · Historias: '+f.usos_historia+(f.ultimo_uso?' · Último uso: '+esc(f.ultimo_uso):'')+'</div><div class="row"><button class="soft sm" onclick="renameBank('+f.id+')">Guardar pie</button><button class="soft sm" onclick="toggleBank('+f.id+')">'+(f.activa?'Pausar':'Activar')+'</button>'+(f.usos_post?'<button class="soft sm" onclick="resetBank('+f.id+')" title="Permite que vuelva a salir como post">Reusar en feed</button>':'')+'</div></div></div>'}).join('')||'<p class="muted">El banco está vacío. Subí fotos con el botón de arriba o conectá Google Drive en Ajustes.</p>'}
async function renameBank(id){if(await act('bank_rename',{id:id,nombre:document.getElementById('bn'+id).value}))loadBank()}
async function useBank(id,uso){if(await act('bank_use',{id:id,uso:uso}))loadBank()}
async function toggleBank(id){if(await act('bank_toggle',{id:id}))loadBank()}
async function resetBank(id){if(!confirm('¿Permitir que esta foto vuelva a publicarse como post?'))return;if(await act('bank_reset',{id:id}))loadBank()}
async function loadMessages(){var d=await api('/api/messages');messages=d.messages;document.getElementById('tgState').textContent=d.telegram?'Telegram conectado: también podés responder desde su chat.':'Telegram no configurado; podés responder acá desde el panel.';document.getElementById('msgs').innerHTML=messages.map(function(m){return '<article class="message"><b>'+esc(m.categoria)+'</b> · <span class="pill">'+esc(m.estado)+'</span><div class="small">'+esc(m.recibido)+' · ID '+esc(m.ig_msg_id)+'</div><p>'+esc(m.texto)+'</p>'+(m.estado==='pendiente_humano'?'<button class="soft" onclick="chooseMessage(\''+esc(m.ig_msg_id)+'\')">Responder</button>':'')+(m.respuesta?'<div class="note">Sugerencia: '+esc(m.respuesta)+'</div>'+(m.estado==='pendiente_humano'?'<button class="soft" onclick="useSuggestion(\''+esc(m.ig_msg_id)+'\')">Usar sugerencia</button>':''):'')+'</article>'}).join('')||'<p class="muted">Todavía no hay mensajes.</p>'}
function chooseMessage(id){selectedMessage=id;var m=messages.find(function(x){return x.ig_msg_id===id});document.getElementById('replyInfo').textContent='Respuesta para mensaje recibido '+m.recibido+'. Se enviará por Instagram.';document.getElementById('sendReply').disabled=false}
function useSuggestion(id){chooseMessage(id);var m=messages.find(function(x){return x.ig_msg_id===id});document.getElementById('replyText').value=m.respuesta||''}
async function sendReply(){var t=document.getElementById('replyText').value.trim();if(!selectedMessage||!t)return alert('Elegí un mensaje y escribí una respuesta.');if(!confirm('¿Enviar esta respuesta por Instagram?'))return;try{await api('/api/action',{action:'reply',ig_msg_id:selectedMessage,text:t});selectedMessage=null;document.getElementById('replyText').value='';document.getElementById('sendReply').disabled=true;await loadMessages();await loadHome();toast('Respuesta enviada')}catch(e){alert(e.message)}}
function renderAudience(d){var totals={};(d.audience||[]).forEach(function(r){var v=r.value;if(v&&typeof v==='object'&&!Array.isArray(v)){Object.keys(v).forEach(function(k){if(/^\d{1,2}$/.test(k)){totals[Number(k)]=(totals[Number(k)]||0)+Number(v[k]||0)}})}});var entries=Object.keys(totals).map(Number).sort(function(a,b){return a-b});if(!entries.length){document.getElementById('audienceNote').textContent=d.audience_note;return}var max=Math.max(1,...entries.map(function(h){return totals[h]}));document.getElementById('audienceNote').innerHTML='<b>Seguidores conectados por hora</b>'+entries.map(function(h){return '<div class="rank"><span>'+h+':00</span><div class="bar"><span style="width:'+Math.max(3,100*totals[h]/max)+'%"></span></div><b>'+totals[h]+'</b></div>'}).join('')}
async function loadMetrics(){var d=await api('/api/metrics');document.getElementById('mKpis').innerHTML=[['Seguidores',d.followers==null?'—':d.followers],['Alcance 14 días',d.reach==null?'—':d.reach],['Publicaciones medidas',d.count],['Likes',d.likes],['Comentarios',d.comments]].map(function(x){return '<div class="card kpi"><small>'+x[0]+'</small><strong>'+x[1]+'</strong></div>'}).join('');var max=Math.max(1,...d.ranking.por_hora.map(function(x){return x.promedio}));document.getElementById('hourChart').innerHTML=d.ranking.por_hora.map(function(x){return '<div class="rank"><span>'+x.hora+':00 · '+x.muestra+'</span><div class="bar"><span style="width:'+Math.max(3,100*x.promedio/max)+'%"></span></div><b>'+x.promedio+'</b></div>'}).join('')||'<p class="muted">Sin datos sincronizados.</p>';document.getElementById('metricNote').textContent=d.ranking.nota;var maxp=Math.max(1,...d.ranking.ranking.map(function(x){return x.promedio}));document.getElementById('peak').innerHTML=d.ranking.ranking.slice(0,6).map(function(x){return '<div class="rank"><b>'+days[x.dia]+' '+x.hora+':00</b><div class="bar"><span style="width:'+Math.max(3,100*x.promedio/maxp)+'%"></span></div><span>'+x.promedio+' · n='+x.muestra+'</span></div>'}).join('')||'<p class="muted">Todavía no hay datos.</p>';renderAudience(d);document.getElementById('topPosts').innerHTML=d.top.length?'<table><tr><th>Descripción</th><th>Fecha</th><th>Likes</th><th>Comentarios</th></tr>'+d.top.map(function(p){return '<tr><td>'+(p.permalink?'<a href="'+esc(p.permalink)+'" target="_blank" rel="noopener">':'')+esc(p.caption||'Sin descripción')+(p.permalink?'</a>':'')+'</td><td>'+esc(p.published.slice(0,10))+'</td><td>'+p.likes+'</td><td>'+p.comentarios+'</td></tr>'}).join('')+'</table>':'<p class="muted">Sin publicaciones sincronizadas.</p>'}
async function syncMetrics(){document.getElementById('syncState').textContent='Sincronizando con Instagram…';try{var d=await api('/api/action',{action:'sync_metrics'});document.getElementById('syncState').textContent='Listo: '+d.synced+' publicaciones actualizadas';await loadMetrics();await loadHome()}catch(e){document.getElementById('syncState').textContent=e.message}}
function v(id,val){document.getElementById(id).value=val==null?'':val}
async function loadSettings(){settings=await api('/api/settings');var tg=document.getElementById('tgSetup');tg.className='note '+(settings.telegram?'':'warn');tg.textContent=settings.telegram?'Telegram conectado (chat '+settings.telegram_chat_id+'). Te llegan avisos de publicaciones, errores y mensajes.':settings.telegram_token?'Token guardado. Falta el paso 3 y 4: enviá /start a tu bot y detectá el chat.':'Seguí estos pasos una sola vez.';
var dr=document.getElementById('driveSetup');var drOk=settings.drive_credentials&&settings.drive_folder;dr.className='note '+(drOk?'':'warn');dr.textContent=drOk?'Drive configurado. Subí fotos a la carpeta y el bot las toma solo.':settings.drive_credentials?'Credenciales cargadas. Falta compartir la carpeta y pegar su link.':'Seguí estos pasos una sola vez (unos 10 minutos).';document.getElementById('driveAccount').textContent=settings.drive_account||'(subí primero el JSON)';
document.getElementById('opStatus').innerHTML=st(settings.running,settings.running?'Bot funcionando':'Bot detenido')+st(settings.autostart,settings.autostart?'Inicio automático activado':'Inicio automático desactivado')+st(true,settings.token_renewed?'Token renovado el '+settings.token_renewed.split('-').reverse().join('/')+' (se renueva solo cada 7 días)':'El token se renueva solo cada 7 días con el bot encendido');document.getElementById('autoBtn').textContent=settings.autostart?'Desactivar inicio automático':'Activar inicio automático';
document.getElementById('aiStatus').textContent=settings.ai_key?'Clave de Anthropic guardada.':'Sin clave de Anthropic: la IA está apagada.';document.getElementById('aiOn').checked=settings.ai_enabled;document.getElementById('autoOn').checked=settings.auto_replies;document.getElementById('autopilot').checked=settings.autopilot;
v('business',settings.business);v('closing',settings.closing);v('hashtags',settings.hashtags);v('storyText',settings.story_text);v('storyCta',settings.story_cta);v('interval',settings.interval);v('storyHour',settings.story_hour);v('noticeDays',settings.post_notice_days);v('brand',settings.brand);v('brandColor',settings.brand_color);v('whatsapp',settings.whatsapp);v('driveFolder',settings.drive_folder);v('tgChat',settings.telegram_chat_id)}
async function discover(){try{var d=await api('/api/telegram/discover',{});var s=document.getElementById('tgCandidates');s.innerHTML='<option value="">Elegí tu chat</option>'+d.chats.map(function(c){return '<option value="'+esc(c.chat_id)+'">'+esc(c.nombre||c.usuario||'Chat privado')+' · '+esc(c.chat_id)+'</option>'}).join('');if(!d.chats.length)alert('No encontré chats. Abrí tu bot en Telegram, enviá /start y volvé a tocar Detectar chat.');else if(d.chats.length===1){s.value=d.chats[0].chat_id;pickChat();toast('Chat detectado. Ahora tocá Guardar ajustes.')}}catch(e){alert(e.message)}}
function pickChat(){document.getElementById('tgChat').value=document.getElementById('tgCandidates').value}
async function uploadCred(f){if(!f)return;var b=await new Promise(function(ok,no){var r=new FileReader();r.onload=function(){ok(r.result.split(',')[1])};r.onerror=no;r.readAsDataURL(f)});document.getElementById('credFile').value='';var d=await act('google_credentials',{data:b});if(d){await loadSettings();alert(d.message)}}
async function toggleAutostart(){var on=!settings.autostart;if(!confirm(on?'¿Hacer que el bot arranque solo cada vez que prendés la PC? También lo enciendo ahora.':'¿Desactivar el inicio automático? El bot que está corriendo sigue hasta que lo detengas.'))return;if(await act('autostart',{on:on})){await loadSettings();await loadHome()}}
async function renewToken(){if(!confirm('¿Renovar ahora el token de Instagram? (el bot lo hace solo cada 7 días)'))return;if(await act('renew_token'))await loadSettings()}
async function saveSettings(){var ai=document.getElementById('aiOn').checked,auto=document.getElementById('autoOn').checked;if(ai&&!settings.ai_key&&!document.getElementById('aiKey').value.trim())return alert('Agregá primero la clave de Anthropic.');if(ai&&!settings.ai_enabled&&!confirm('La IA enviará textos y fotos a Anthropic. ¿Habilitar?'))return;if(auto&&!settings.auto_replies&&!confirm('Se enviarán respuestas automáticas a clientes de Instagram. ¿Activarlas?'))return;
var b={telegram_token:document.getElementById('tgToken').value,telegram_chat_id:document.getElementById('tgChat').value,anthropic_key:document.getElementById('aiKey').value,ai_enabled:ai,auto_replies:auto,autopilot:document.getElementById('autopilot').checked,business:document.getElementById('business').value,closing:document.getElementById('closing').value,hashtags:document.getElementById('hashtags').value,story_text:document.getElementById('storyText').value,story_cta:document.getElementById('storyCta').value,interval:document.getElementById('interval').value,story_hour:document.getElementById('storyHour').value,post_notice_days:document.getElementById('noticeDays').value,brand:document.getElementById('brand').value,brand_color:document.getElementById('brandColor').value,whatsapp:document.getElementById('whatsapp').value,drive_folder:document.getElementById('driveFolder').value};
try{var d=await api('/api/settings',b);document.getElementById('tgToken').value='';document.getElementById('aiKey').value='';await loadSettings();await loadHome();toast(d.restarted?'Ajustes guardados; reinicié el bot para aplicarlos':'Ajustes guardados')}catch(e){alert(e.message)}}
var ads={zonas:[]};
function money(n,m){return (m||'')+' '+Math.round(n||0).toLocaleString('es-AR')}
async function loadAds(){ads=await api('/api/ads');var g=ads.gasto||{};var pres=g.presupuesto||0,gas=g.gastado||0;var pct=pres?Math.min(100,100*gas/pres):0;
document.getElementById('adsSpend').innerHTML=ads.campana_mes?'<div class="kpi"><small>Gastado este mes</small><strong>'+money(gas,g.moneda)+' <span class="muted" style="font-size:16px">de '+money(pres,g.moneda)+'</span></strong></div><div class="bar" style="margin:10px 0"><span style="width:'+Math.max(2,pct)+'%"></span></div><div class="small">Alcance: '+(g.alcance||0).toLocaleString('es-AR')+' personas · Impresiones: '+(g.impresiones||0).toLocaleString('es-AR')+' · Conversaciones iniciadas: '+(g.conversaciones||0)+'</div>':'<p class="muted">Todavía no hay campaña este mes. Se crea al activar la publicidad con al menos una publicación elegida.</p>';
document.getElementById('adsStatus').innerHTML=st(ads.configurada,ads.configurada?'Cuenta publicitaria conectada ('+esc(ads.cuenta)+')':'Falta conectar la cuenta publicitaria (abajo)')+st(ads.activa?true:null,ads.activa?'Publicidad activada':'Publicidad apagada')+st(!!ads.presupuesto,ads.presupuesto?'Presupuesto: '+money(ads.presupuesto)+' por mes':'Falta definir el presupuesto')+st(ads.zonas.length?true:false,ads.zonas.length?ads.zonas.length+' zona(s) elegidas':'Falta elegir zonas')+st(ads.promocionados.length?true:null,ads.promocionados.length+' publicación(es) promocionadas');
document.getElementById('adsToggleBtn').textContent=ads.activa?'Pausar publicidad':'Activar publicidad';document.getElementById('adsToggleBtn').className=ads.activa?'red':'';
v('adsBudget',ads.presupuesto);document.getElementById('adsGoal').value=ads.objetivo==='alcance'?'alcance':'mensajes';
var su=document.getElementById('adsSetup');su.className='note '+(ads.configurada?'':'warn');su.textContent=ads.configurada?'Cuenta conectada. Si cambiás de cuenta o vence el token, repetí el paso 4.':'Se hace una sola vez. Usá un "usuario del sistema" para que el token no venza.';
renderZones();document.getElementById('adsPosts').innerHTML=(ads.error_posts?'<div class="note bad">No pude traer tus publicaciones: '+esc(ads.error_posts)+'</div>':'')+ads.posts.map(function(p){return '<div class="photo"><img loading="lazy" src="'+esc(p.imagen)+'" referrerpolicy="no-referrer"><div class="body"><div class="row">'+(p.promocionado?'<span class="pill auto">promocionando</span>':'')+'<span class="small">'+esc(p.fecha)+' · '+p.likes+' likes</span></div><div class="small" style="color:#263b2e">'+esc(p.caption||'Sin descripción')+'</div><div class="row">'+(p.promocionado?'<button class="soft sm" onclick="adsUnpromote(\''+p.id+'\')">Dejar de promocionar</button>':'<button class="sm" onclick="adsPromote(\''+p.id+'\')">Promocionar</button>')+'<a class="small" href="'+esc(p.link)+'" target="_blank" rel="noopener">Ver</a></div></div></div>'}).join('')}
function renderZones(){document.getElementById('zoneList').innerHTML=ads.zonas.length?'<table>'+ads.zonas.map(function(z,i){return '<tr><td><b>'+esc(z.nombre)+'</b><div class="small">'+esc(z.detalle||z.tipo)+'</div></td><td>'+(z.tipo==='city'?'<select onchange="zoneRadius('+i+',this.value)"><option value="">Solo la ciudad</option>'+[17,25,40,60,80].map(function(r){return '<option value="'+r+'"'+(String(z.radio)===String(r)?' selected':'')+'>+'+r+' km</option>'}).join('')+'</select>':'')+'</td><td><button class="soft sm" onclick="zoneRemove('+i+')">Quitar</button></td></tr>'}).join('')+'</table>':'<p class="muted">Ninguna todavía.</p>'}
async function zoneSearch(){var q=document.getElementById('zoneQ').value.trim();if(!q)return;try{var d=await api('/api/action',{action:'ads_search',q:q});document.getElementById('zoneResults').innerHTML=d.zonas.length?'<table>'+d.zonas.map(function(z,i){return '<tr><td><b>'+esc(z.nombre)+'</b><div class="small">'+esc(z.detalle)+'</div></td><td><button class="sm" onclick=\'zoneAdd('+JSON.stringify(z).replace(/'/g,"&#39;")+')\'>Agregar</button></td></tr>'}).join('')+'</table>':'<p class="muted">Sin resultados.</p>'}catch(e){alert(e.message)}}
async function saveZones(){var d=await act('ads_zones',{zonas:ads.zonas});if(d)loadAds()}
function zoneAdd(z){if(ads.zonas.some(function(x){return x.key===z.key}))return toast('Esa zona ya está');ads.zonas.push(z);document.getElementById('zoneResults').innerHTML='';document.getElementById('zoneQ').value='';saveZones()}
function zoneRemove(i){ads.zonas.splice(i,1);saveZones()}
function zoneRadius(i,r){if(r)ads.zonas[i].radio=Number(r);else delete ads.zonas[i].radio;saveZones()}
async function adsBudget(){var m=Number(document.getElementById('adsBudget').value);if(!(m>0))return alert('Escribí el monto mensual.');if(!confirm('¿Fijar el presupuesto de publicidad en '+money(m)+' por mes? Meta nunca va a gastar más que eso en el mes.'))return;if(await act('ads_budget',{monto:m,objetivo:document.getElementById('adsGoal').value}))loadAds()}
async function adsToggle(){var on=!ads.activa;if(on&&!confirm('¿Activar la publicidad paga? Meta va a cobrar a tu medio de pago hasta '+money(ads.presupuesto)+' por mes (proporcional a los días que quedan de este mes).'))return;if(!on&&!confirm('¿Pausar la publicidad? Deja de gastar enseguida.'))return;toast('Un momento…');if(await act('ads_toggle',{on:on}))loadAds()}
async function adsPromote(id){var p=ads.posts.find(function(x){return x.id===id});if(!confirm('¿Promocionar esta publicación con el presupuesto del mes?'))return;toast('Creando el anuncio…');if(await act('ads_promote',{id:id,caption:p?p.caption:'',link:p?p.link:''}))loadAds()}
async function adsUnpromote(id){if(!confirm('¿Dejar de promocionar esta publicación?'))return;if(await act('ads_unpromote',{id:id}))loadAds()}
async function adsRefresh(){if(await act('ads_refresh'))loadAds()}
async function adsConnect(){var t=document.getElementById('adsToken').value.trim();if(!t)return alert('Pegá el token.');try{var d=await api('/api/action',{action:'ads_accounts',token:t});document.getElementById('adsToken').value='';var s=document.getElementById('adsAccounts');if(!d.cuentas.length)return alert('El token funciona, pero no tiene ninguna cuenta publicitaria asignada. Revisá el paso 2.');s.innerHTML='<option value="">Elegí tu cuenta publicitaria</option>'+d.cuentas.map(function(c){return '<option value="'+esc(c.id)+'">'+esc(c.nombre)+' · '+esc(c.moneda)+' · '+esc(c.id)+'</option>'}).join('');s.style.display='';if(d.cuentas.length===1){s.value=d.cuentas[0].id;adsPickAccount(s.value)}}catch(e){alert(e.message)}}
async function adsPickAccount(id){if(!id)return;var d=await act('ads_account',{id:id});document.getElementById('adsAccounts').style.display='none';if(d)loadAds()}
async function init(){await loadHome();setInterval(function(){if(document.getElementById('home').classList.contains('on'))loadHome();else api('/api/summary').then(function(d){setRunning(d.running)});if(document.getElementById('content').classList.contains('on')&&!dirty)loadPosts()},15000)}init();
</script></body></html>'''
